function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function getTelegramContext(source) {
  const payload = source.payload || {};
  const message = source.message || payload.message || payload.body?.message || {};
  const chatId = source.chatId || message.chat?.id || payload.chatId || '';
  const rawText = String(
    source.rawText || source.text || message.text || message.caption || payload.text || payload.rawText || ''
  ).trim();
  return { payload, message, chatId, rawText };
}

const source = $input.item.json || {};
const ctx = getTelegramContext(source);
const text = normalize(ctx.rawText);
const hasAny = (keywords) => keywords.some((k) => text.includes(k));

let action = 'help';

if (hasAny(['sheets help', 'google sheets help', 'huong dan sheets', 'sheet help'])) {
  action = 'help';
} else if (hasAny(['tao sheet', 'tao bang tinh', 'create sheet'])) {
  action = 'create_sheet';
} else if (hasAny(['them dong vao sheet', 'append row'])) {
  action = 'append_row';
} else if (hasAny(['cap nhat sheet', 'cap nhat o', 'update cell'])) {
  action = 'update_cell';
} else if (hasAny(['doc sheet', 'xem sheet', 'read sheet'])) {
  action = 'read_sheet';
} else if (hasAny(['tim sheet', 'search sheet', 'tim bang tinh'])) {
  action = 'search_sheet';
} else if (hasAny(['xoa sheet', 'delete sheet', 'xoa bang tinh'])) {
  action = 'delete_sheet';
}

return [{
  json: {
    ...source,
    payload: ctx.payload,
    message: ctx.message,
    chatId: ctx.chatId,
    rawText: ctx.rawText,
    text,
    action
  }
}];

const workflowMap = {
  create_sheet: 'Sub-workflow: Google Sheets - Create Sheet',
  read_sheet: 'Sub-workflow: Google Sheets - Read Sheet',
  append_row: 'Sub-workflow: Google Sheets - Append Row',
  update_cell: 'Sub-workflow: Google Sheets - Update Cell',
  search_sheet: 'Sub-workflow: Google Sheets - Search Sheet',
  delete_sheet: 'Sub-workflow: Google Sheets - Delete Sheet',
  help: 'Sub-workflow: Google Sheets - Help'
};

return [{ json: { ...$json, workflowName: workflowMap[$json.action] || workflowMap.help } }];

const workflows = $input.item.json.data || [];
const source = $('Chon Workflow Sheets').item.json || {};
const found = workflows.find((workflow) => workflow.name === source.workflowName);
if (!found) {
  return [{ json: { ...source, hasWorkflow: false, response: 'Khong tim thay workflow con: ' + source.workflowName } }];
}
return [{ json: { ...source, hasWorkflow: true, workflowId: found.id } }];
